function ENUMERATE(N):
    d_max = ceil(sqrt((N - 5) / 2)) + 1
    queue = [(3, 4, 5)]
    result = []
    while queue not empty:
        (a, b, c) = queue.pop()
        if c > N: continue
        result.add((a, b, c))
        for gen in [A, B, C]:
            (a_new, b_new, c_new) = gen(a, b, c)
            if c_new <= N: queue.push((a_new, b_new, c_new))
    return result
